@startuml

class EBike {
}

class Frame {
  + material : string
}

class DriveSystem {
}

class Motor {
}

class Controller {
  + state : ControllerState
}

class BasicController extends Controller {}

class AdvancedController extends Controller {
  + nextMaintenanceDate : date
}

class Battery {
  + storedEnergy : double
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "1" "0..1" -- "1" Battery : connected to
Frame "1" *-- "2" Wheel {}
DriveSystem "1" *-- "1" Motor
Controller "1" -- "0..1" Battery : controls
Controller "1" -- "1" DriveSystem : commands

@enduml

